"""Render docs/SCHEMA_RECONCILIATION.md from tools/reconciliation.json (run tools/reconcile.py first)."""
import json

r = json.load(open(r'D:\Sims_2\tools\reconciliation.json'))
c = r['counts']
interp = {
    'class_session': 'Lesson Plan link; out of scope',
    'file_object': 'Virus-scan / encryption-key metadata; backlog (relevant to storage phase, needs decision)',
    'user_account': 'Django auth fields; replaced by Supabase Auth + identity map, not migrated',
}
L = [
    '# Schema Reconciliation: SQL (authoritative) vs Data Dictionary', '',
    'Generated by `tools/reconcile.py` and `tools/write_reconciliation_md.py` (re-runnable). Date: 2026-11-03.', '',
    '## Counts', '| Object | SQL file | Dictionary |', '|---|---|---|',
    f"| Tables | {c['sql_tables']} | {c['dd_tables']} |",
    f"| Views | {c['sql_views']} | {c['dd_views']} |",
    f"| Triggers | {c['sql_triggers']} | not documented |",
    f"| Columns (SQL tables) | {r['sql_columns_total']} | - |", '',
    '## Result',
    '- Tables in SQL but not in dictionary: **none**.',
    '- All 10 SQL views are documented in the dictionary.',
    '- Column sets match for 211 of 213 shared tables; 2 differ (below). An earlier draft listed file_object here; that was a parser artefact (see DATABASE_MIGRATION.md).', '',
    '## Shared tables whose columns differ (dictionary has more)',
    '| Table | Dictionary-only columns | Interpretation |', '|---|---|---|',
]
for t, d in r['col_diffs'].items():
    L.append(f"| `{t}` | {', '.join(d['dict_only'])} | {interp[t]} |")
L += ['', '## Dictionary-only tables (52) – NOT migrated; backlog', '| Module | Count |', '|---|---|']
for k, v in r['dict_only_by_module'].items():
    L.append(f'| {k} | {v} |')
L += ['', 'Tables: ' + ', '.join(f'`{t}`' for t in r['dict_only_tables']), '',
      '## Dictionary-only views (11) – NOT migrated; backlog', ', '.join(f'`{v}`' for v in r['views_dict_not_sql']), '',
      '## Triggers in SQL (16, all to be ported)', ', '.join(f'`{t}`' for t in r['triggers']), '',
      '## Source tables per dictionary module', '| Module | Tables |', '|---|---|']
for k, v in sorted(r['tables_by_module_sql'].items()):
    L.append(f'| {k} | {v} |')
L += ['', '## Not yet done',
      'Constraint-level equivalence (PK/FK/UQ/CHECK/index/trigger/view/seed) will be reported in `docs/DATABASE_MIGRATION.md` after the Postgres migration has actually been executed. Nothing here claims that has happened.', '']
open(r'D:\Sims_2\docs\SCHEMA_RECONCILIATION.md', 'w', encoding='utf-8').write('\n'.join(L))
